\path (-1.9,1.8) node {b};
\draw[<->,thick,graphblue] (-1.8,-0.9)--(1.8,0.9);
\end{scope}
\begin{scope}[yshift=-5.5cm]
\draw[<->] (-2,0)--(2,0);
\draw[<->] (0,-2)--(0,2);
\path (2,0) node[right] {$x$};
\path (0,2) node[above] {$y$};
\path (-1.9,1.8) node {c};
\draw[thick,graphblue] (0,0) circle (1.3);
\end{scope}
\begin{scope}[xshift=5.5cm,yshift=-5.5cm]
\draw[<->] (-2,0)--(2,0);
